import { test, expect } from '@playwright/test';

test.describe('Lazy-loaded Components Smooth Loading', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/lazy-components');
  });

  test('should load lazy-loaded components smoothly without layout shift', async ({ page }) => {
    // Verify initial state - no lazy-loaded components should be visible
    const lazyComponentContainer = page.getByRole('region', { name: /lazy-loaded content/i });
    await expect(lazyComponentContainer).toBeVisible();

    // Verify initial content is empty
    const lazyComponentContent = page.getByText(/loading/i);
    await expect(lazyComponentContent).toBeVisible();

    // Verify initial layout is stable
    const layoutStability = page.getByRole('heading', { name: /Layout Stability/i });
    await expect(layoutStability).toBeVisible();

    // Trigger lazy loading by scrolling
    await page.evaluate(() => {
      window.scrollBy(0, 1000);
    });

    // Wait for lazy-loaded component to load
    await page.waitForTimeout(500);

    // Verify lazy-loaded component appears smoothly
    await expect(lazyComponentContainer).toBeVisible();

    // Verify content is now visible
    const lazyComponentContent = page.getByText(/content/i);
    await expect(lazyComponentContent).toBeVisible();

    // Verify no layout shift occurred
    const layoutStability = page.getByRole('heading', { name: /Layout Stability/i });
    await expect(layoutStability).toBeVisible();

    // Verify smooth transition
    const transitionClass = page.getByTestId('transition-class');
    await expect(transitionClass).toBeVisible();
  });

  test('should handle failed lazy-loaded component loading gracefully', async ({ page }) => {
    // Trigger lazy loading by scrolling
    await page.evaluate(() => {
      window.scrollBy(0, 1000);
    });

    // Wait for lazy-loaded component to load
    await page.waitForTimeout(500);

    // Simulate failed loading by intercepting network request
    await page.route('**/lazy-component-data', route => {
      route.abort('Failed to load');
    });

    // Verify error state is displayed
    const errorState = page.getByText(/error/i);
    await expect(errorState).toBeVisible();

    // Verify loading indicator is still visible
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();

    // Verify layout remains stable
    const layoutStability = page.getByRole('heading', { name: /Layout Stability/i });
    await expect(layoutStability).toBeVisible();

    // Verify user is notified of error
    const errorMessage = page.getByText(/Failed to load component/i);
    await expect(errorMessage).toBeVisible();

    // Verify user can retry or navigate away
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify navigation away button is available
    const navigationButton = page.getByRole('button', { name: /navigate away/i });
    await expect(navigationButton).toBeVisible();
  });
});
